<?php require"config/auth.php";require"config/db.php";if(isset($_GET["delete"])){$id=(int)$_GET["delete"];$conn->query("DELETE FROM members WHERE id=$id");header("Location:members.php");exit;}if($_SERVER["REQUEST_METHOD"]==="POST"){$n=trim($_POST["name"]);$e=trim($_POST["email"]);$p=trim($_POST["phone"]);$a=trim($_POST["address"]);$s=$conn->prepare("INSERT INTO members(name,email,phone,address) VALUES(?,?,?,?)");$s->bind_param("ssss",$n,$e,$p,$a);$s->execute();header("Location:members.php");exit;}$rows=$conn->query("SELECT * FROM members ORDER BY id DESC");?><!doctype html><html><head><title>Members</title><link rel="stylesheet" href="assets/style.css"></head><body><?php include"nav.php";?><main class="container"><h1>Members</h1><div class="card"><h2>Add Member</h2><form method="post" class="grid"><div><label>Name</label><input name="name" required></div><div><label>Email</label><input type="email" name="email"></div><div><label>Phone</label><input name="phone"></div><div><label>Address</label><input name="address"></div><div style="align-self:end"><button class="btn">Add Member</button></div></form></div><div class="card"><table><tr><th>ID</th><th>Name</th><th>Email</th><th>Phone</th><th>Address</th><th>Action</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=$r["id"]?></td><td><?=htmlspecialchars($r["name"])?></td><td><?=htmlspecialchars($r["email"])?></td><td><?=htmlspecialchars($r["phone"])?></td><td><?=htmlspecialchars($r["address"])?></td><td><a class="btn danger" href="?delete=<?=$r["id"]?>" onclick="return confirm('Delete this member?')">Delete</a></td></tr><?php endwhile;?></table></div></main></body></html>